void UEnemyPresenceComponent::TickComponent(float DeltaTime...)
{
    // 1. Logic: Find closest enemy & calculate distance
    UpdateClosestEnemy();

    // 2. Math: Normalize distance to 0.0 - 100.0 range
    float NormDist = (Distance - MinDist) / (MaxDist - MinDist);
    float Proximity = FMath::Clamp((1.f - NormDist) * 100.f, 0.f, 100.f);

    // 3. Audio: Update Wwise RTPC in real-time
    UAkGameplayStatics::SetRTPCValue(
        RTPC_EnemyProximity,
        Proximity,
        0, // Interpolation (handled by Wwise)
        GetOwner()
    );

    // 4. Debug: Visual confirmation
    if (bShowDebug) DrawDebugLine(..., FColor::Red);
}

void UAnomalyAudioManager::InitializeAudioSource(AActor* Owner)
{
    const FAnomalyAudioSettings* Settings = Config->GetSettings(Anomaly);

    // Advanced Spatial Audio: Find specific mesh bone
    if (Settings->SpecialMeshName != NAME_None)
    {
        USceneComponent* Target = FindComponentByName(Owner, Settings->SpecialMeshName);
        if (Target) {
            AkComponent->AttachToComponent(Target, FAttachmentTransformRules::KeepRelativeTransform);
        }
    }

    UAkGameplayStatics::PostEvent(
        Config->m_GlobalSpawnEvent,
        AkComponent
    );
}

FName UFootstepComponent::DetectSurface()
{
    FHitResult Hit;
    FVector Start = Location;
    FVector End = Start - FVector(0, 0, 100);

    // Physics Query
    bool bHit = World->LineTraceSingleByChannel(
        Hit, Start, End, ECC_WorldStatic, Params
    );

    // Map Physical Material to Wwise Switch
    if (bHit && Hit.PhysMaterial.IsValid())
    {
        return GetSwitchFromPhysMat(Hit.PhysMaterial);
    }

    return "Concrete"; // Fallback
}

if (tremoloOn && tremDepth > 0.0f)
{
    float phaseInc = (float)(2.0 * juce::MathConstants<double>::pi * tremRate / currentSR);

    for (int sample = 0; sample < numSamples; ++sample)
    {
        float lfoVal = 0.5f + 0.5f * std::sin(tremoloPhase);
        float amplitude = (1.0f - tremDepth) + (tremDepth * lfoVal);

        for (int ch = 0; ch < numChannels; ++ch)
        {
            float* writePtr = buffer.getWritePointer(ch);
            writePtr[sample] *= amplitude;
        }

        tremoloPhase += phaseInc;
        if (tremoloPhase > juce::MathConstants<float>::twoPi)
            tremoloPhase -= juce::MathConstants<float>::twoPi;
    }
}

void processBlock(juce::AudioBuffer<float>& buffer, juce::MidiBuffer& midiMessages)
{
    if (dangerousVolumeDetected) {
        buffer.clear();
        return;
    }

    float gainValue = *apvts.getRawParameterValue("GAIN");
    float tempoValue = *apvts.getRawParameterValue("TEMPO");

    // Resampling based on tempo
    double ratio = (double)tempoValue / 120.0;
    audioFilePlayer.setResamplingRatio(ratio);

    // Fill buffer from file
    juce::AudioSourceChannelInfo info(buffer);
    audioFilePlayer.getNextAudioBlock(info);

    // Apply DSP chain
    juce::dsp::AudioBlock<float> dspBlock(buffer);
    juce::dsp::ProcessContextReplacing<float> ctx(dspBlock);
    compressor.process(ctx);

    buffer.applyGain(gainValue);
}

void prepareToPlay(double sampleRate, int samplesPerBlock)
{
    juce::dsp::ProcessSpec spec;
    spec.sampleRate = sampleRate;
    spec.maximumBlockSize = (juce::uint32)samplesPerBlock;
    spec.numChannels = 2;

    lpf.setType(juce::dsp::StateVariableTPTFilterType::lowpass);
    hpf.setType(juce::dsp::StateVariableTPTFilterType::highpass);
    lpf.prepare(spec);
    hpf.prepare(spec);

    compressor.prepare(spec);
    compressor.reset();
}

void loadFile(juce::File file)
{
    auto* reader = formatManager.createReaderFor(file);
    if (reader != nullptr) {
        auto* source = new juce::AudioFormatReaderSource(reader, true);
        resamplingSource.setSource(source, 0, nullptr, reader->sampleRate);
        resamplingSource.setResamplingRatio(1.0);
        transportSource.setSource(&resamplingSource, 0, nullptr, reader->sampleRate);
    }
}

void setResamplingRatio(double ratio) {
    resamplingSource.setResamplingRatio(ratio);
}

