public void TogglePauseState(bool isPaused)
{
    if (isPaused)
    {
        // Transition to 'Dread' Snapshot
        audioMixer.TransitionToSnapshot(pausedSnapshot, 0.5f);

        // Start rising tension drone
        tensionSource.Play();
        StartCoroutine(FadeInTension(2.0f));
    }
    else
    {
        // Snap back to reality
        audioMixer.TransitionToSnapshot(gameplaySnapshot, 0.1f);
        tensionSource.Stop();
        PlayStinger(resumeStinger);
    }
}

def scan_for_broken_refs(project_dir):
    broken_files = []
    for root, dirs, files in os.walk(project_dir):
        for file in files:
            if file.endswith(".uasset"):
                path = os.path.join(root, file)
                with open(path, 'rb') as f:
                    content = f.read()
                    # Look for AkAudioEvent signature but missing valid index
                    if b'AkAudioEvent' in content and b'None' in content:
                        broken_files.append(path)
    return broken_files
